ve:|Memory:'\\"\\nssh root@192.168.100.101 \\"journalctl -u kubelet -u etcd -u containerd --since '1 hour ago' --no-pager | grep -i -E 'oom|kill|memory|swap' | head -10\\"\\nssh root@192.168.100.101 \\"free -h && swapon --show\\""}, "kbArticleReference": "KB_NEW"}
